268→    private static string FormatEnumerable(global::System.Collections.IEnumerable enumerable)
269→    {
270→        const int maxItems = 8;
271→        var items = new List<string>();
272→        var count = 0;
273→        foreach (var item in enumerable)
274→        {
275→            if (count < maxItems)
276→                items.Add(FormatValue(item));
277→            count++;
278→        }
279→        var result = string.Join(", ", items);
280→        if (count > maxItems)
281→            result += ", ...";
282→        return $"[{result}]";
283→    }
