using System.Collections.Generic;
using DefaultEcs;
using DefaultEcs.System;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using MonoDreams.Component;
using MonoDreams.Component.Collision;
using MonoDreams.Component.Draw;
using MonoDreams.Draw;
using MonoDreams.State;

namespace MonoDreams.System.Debug;

/// <summary>
/// Per-frame debug visualization for BoxCollider and ConvexCollider shapes.
/// Creates ephemeral mesh entities each frame that render colored outlines:
/// red = active, green = passive, gray = disabled.
/// </summary>
public class ColliderDebugSystem : ISystem<GameState>
{
    public static bool Enabled = true;

    private const float DebugLayerDepth = 1f;
    private const float LineThickness = 0.5f;

    private readonly World _world;
    private readonly EntitySet _colliderEntities;
    private readonly List<Entity> _debugEntities = [];

    public ColliderDebugSystem(World world)
    {
        _world = world;
        _colliderEntities = world.GetEntities()
            .With<ColliderTag>()
            .With<Transform>()
            .AsSet();
    }

    public bool IsEnabled { get; set; } = true;

    public void Update(GameState state)
    {
        foreach (var entity in _debugEntities)
        {
            if (entity.IsAlive)
                entity.Dispose();
        }
        _debugEntities.Clear();

        if (!IsEnabled || !Enabled) return;

        foreach (var entity in _colliderEntities.GetEntities())
        {
            ref readonly var transform = ref entity.Get<Transform>();

            if (entity.Has<BoxCollider>())
            {
                ref readonly var box = ref entity.Get<BoxCollider>();
                CreateBoxOutline(transform, box);
            }

            if (entity.Has<ConvexCollider>())
            {
                var convex = entity.Get<ConvexCollider>();
                CreateConvexOutline(convex);
            }
        }
    }

    private void CreateBoxOutline(in Transform transform, in BoxCollider box)
    {
        var color = GetDebugColor(box);

        var topLeft = new Vector2(
            transform.WorldPosition.X + box.Bounds.Left,
            transform.WorldPosition.Y + box.Bounds.Top);
        var topRight = new Vector2(
            transform.WorldPosition.X + box.Bounds.Right,
            transform.WorldPosition.Y + box.Bounds.Top);
        var bottomRight = new Vector2(
            transform.WorldPosition.X + box.Bounds.Right,
            transform.WorldPosition.Y + box.Bounds.Bottom);
        var bottomLeft = new Vector2(
            transform.WorldPosition.X + box.Bounds.Left,
            transform.WorldPosition.Y + box.Bounds.Bottom);

        var vertices = new List<VertexPositionColor>();
        var indices = new List<int>();
        int indexOffset = 0;

        LineMeshGenerator.AddLine(vertices, indices, topLeft, topRight, LineThickness, color, ref indexOffset);
        LineMeshGenerator.AddLine(vertices, indices, topRight, bottomRight, LineThickness, color, ref indexOffset);
        LineMeshGenerator.AddLine(vertices, indices, bottomRight, bottomLeft, LineThickness, color, ref indexOffset);
        LineMeshGenerator.AddLine(vertices, indices, bottomLeft, topLeft, LineThickness, color, ref indexOffset);

        CreateDebugEntity(vertices, indices);
    }

    private void CreateConvexOutline(ConvexCollider convex)
    {
        var color = GetDebugColor(convex);
        var verts = convex.WorldVertices;
        if (verts == null || verts.Length < 3) return;

        var vertices = new List<VertexPositionColor>();
        var indices = new List<int>();
        int indexOffset = 0;

        for (int i = 0; i < verts.Length; i++)
        {
            var start = verts[i];
            var end = verts[(i + 1) % verts.Length];
            LineMeshGenerator.AddLine(vertices, indices, start, end, LineThickness, color, ref indexOffset);
        }

        CreateDebugEntity(vertices, indices);
    }

    private void CreateDebugEntity(List<VertexPositionColor> vertices, List<int> indices)
    {
        var entity = _world.CreateEntity();
        _debugEntities.Add(entity);

        entity.Set(new DrawComponent
        {
            Type = DrawElementType.Mesh,
            Vertices = vertices.ToArray(),
            Indices = indices.ToArray(),
            PrimitiveType = PrimitiveType.TriangleList,
            Target = RenderTargetID.Main,
            LayerDepth = DebugLayerDepth
        });
        entity.Set<Visible>();
    }

    private static Color GetDebugColor(ICollider collider)
    {
        if (!collider.Enabled) return Color.Gray;
        return collider.Passive ? Color.Green : Color.Red;
    }

    public void Dispose()
    {
        foreach (var entity in _debugEntities)
        {
            if (entity.IsAlive)
                entity.Dispose();
        }
        _debugEntities.Clear();
        _colliderEntities.Dispose();
    }
}

using System;
using System.Collections.Generic;
using DefaultEcs;
using DefaultEcs.System;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using MonoDreams.Component;
using MonoDreams.Component.Draw;
using MonoDreams.State;

namespace MonoDreams.System.Debug;

/// <summary>
/// Debug visualization system for sprite rendering.
/// Renders semi-transparent rectangles showing sprite boundaries and yellow circles at origin points.
/// </summary>
public class SpriteDebugSystem : ISystem<GameState>
{
    /// <summary>
    /// Global toggle for sprite debug visualization.
    /// </summary>
    public static bool Enabled = true;

    private const float DebugLayerDepth = 0.98f;
    private const float OriginCircleRadius = 0.2f;
    private const int CircleSegments = 12;
    private const float LineThickness = 0.1f;

    private readonly World _world;
    private readonly EntitySet _spriteEntities;
    private readonly RenderTargetID _renderTarget;

    // Track debug entities for cleanup
    private readonly List<Entity> _debugEntities = [];

    // Colors
    private static readonly Color BoundsColor = new(0, 0, 0, 50);
    private static readonly Color OriginColor = Color.Orange;

    public SpriteDebugSystem(World world, RenderTargetID renderTarget = RenderTargetID.Main)
    {
        _world = world;
        _renderTarget = renderTarget;

        _spriteEntities = world.GetEntities()
            .With<DrawComponent>()
            .With<SpriteInfo>()
            .With<Transform>()
            .AsSet();
    }

    public bool IsEnabled { get; set; } = true;

    public void Update(GameState state)
    {
        // Clean up old debug entities
        foreach (var entity in _debugEntities)
        {
            if (entity.IsAlive)
            {
                entity.Dispose();
            }
        }
        _debugEntities.Clear();

        if (!IsEnabled || !Enabled) return;

        // Create debug visuals for each sprite entity
        foreach (var entity in _spriteEntities.GetEntities())
        {
            ref readonly var drawComponent = ref entity.Get<DrawComponent>();

            // Only visualize sprite types
            if (drawComponent.Type != DrawElementType.Sprite) continue;
            if (drawComponent.Size == Vector2.Zero) continue;

            // Get the position and origin from DrawComponent
            var position = drawComponent.Position;
            var origin = drawComponent.Origin;
            var size = drawComponent.Size;

            // Calculate the top-left corner of the sprite bounds
            // Origin is in SOURCE texture coordinates, so we need to scale it to destination size
            // scale = destinationSize / sourceSize
            Vector2 scaledOrigin;
            if (drawComponent.SourceRectangle.HasValue &&
                drawComponent.SourceRectangle.Value.Width > 0 &&
                drawComponent.SourceRectangle.Value.Height > 0)
            {
                scaledOrigin = new Vector2(
                    origin.X * size.X / drawComponent.SourceRectangle.Value.Width,
                    origin.Y * size.Y / drawComponent.SourceRectangle.Value.Height);
            }
            else
            {
                scaledOrigin = origin;
            }

            // When rendering, SpriteBatch places the scaled origin at position
            // So bounds top-left = position - scaledOrigin
            var boundsTopLeft = position - scaledOrigin;

            // Create bounds rectangle (semi-transparent black)
            CreateFilledRectEntity(boundsTopLeft.X, boundsTopLeft.Y, size.X, size.Y, BoundsColor);

            // Create origin circle (yellow) at the position
            CreateCircleEntity(position.X, position.Y, OriginCircleRadius, OriginColor);

            // Create line from origin to center of bounds
            var boundsCenter = boundsTopLeft + size / 2;
            CreateLineEntity(position, boundsCenter, OriginColor);
        }
    }

    private void CreateFilledRectEntity(float x, float y, float width, float height, Color color)
    {
        var entity = _world.CreateEntity();
        _debugEntities.Add(entity);

        // Create a filled rectangle with 4 vertices and 2 triangles
        var vertices = new VertexPositionColor[]
        {
            new(new Vector3(x, y, 0), color),                         // Top-left
            new(new Vector3(x + width, y, 0), color),                 // Top-right
            new(new Vector3(x + width, y + height, 0), color),        // Bottom-right
            new(new Vector3(x, y + height, 0), color),                // Bottom-left
        };

        var indices = new int[]
        {
            0, 1, 2,  // First triangle
            0, 2, 3   // Second triangle
        };

        entity.Set(new DrawComponent
        {
            Type = DrawElementType.Mesh,
            Vertices = vertices,
            Indices = indices,
            PrimitiveType = PrimitiveType.TriangleList,
            Target = _renderTarget,
            LayerDepth = DebugLayerDepth
        });
    }

    private void CreateCircleEntity(float centerX, float centerY, float radius, Color color)
    {
        var entity = _world.CreateEntity();
        _debugEntities.Add(entity);

        // Create a filled circle using triangle fan
        var vertices = new List<VertexPositionColor>();
        var indices = new List<int>();

        // Center vertex
        vertices.Add(new VertexPositionColor(new Vector3(centerX, centerY, 0), color));

        // Perimeter vertices
        for (int i = 0; i <= CircleSegments; i++)
        {
            var angle = (float)(i * 2 * Math.PI / CircleSegments);
            var px = centerX + radius * MathF.Cos(angle);
            var py = centerY + radius * MathF.Sin(angle);
            vertices.Add(new VertexPositionColor(new Vector3(px, py, 0), color));
        }

        // Create triangles (triangle fan from center)
        for (int i = 1; i <= CircleSegments; i++)
        {
            indices.Add(0);       // Center
            indices.Add(i);       // Current perimeter vertex
            indices.Add(i + 1);   // Next perimeter vertex
        }

        entity.Set(new DrawComponent
        {
            Type = DrawElementType.Mesh,
            Vertices = vertices.ToArray(),
            Indices = indices.ToArray(),
            PrimitiveType = PrimitiveType.TriangleList,
            Target = _renderTarget,
            LayerDepth = DebugLayerDepth + 0.001f  // Slightly in front of bounds
        });
    }

    private void CreateLineEntity(Vector2 start, Vector2 end, Color color)
    {
        var entity = _world.CreateEntity();
        _debugEntities.Add(entity);

        // Calculate perpendicular direction for line thickness
        var direction = end - start;
        if (direction.LengthSquared() < 0.0001f) return;

        var perpendicular = new Vector2(-direction.Y, direction.X);
        perpendicular.Normalize();
        perpendicular *= LineThickness / 2;

        // Create a quad (thick line) with 4 vertices
        var vertices = new VertexPositionColor[]
        {
            new(new Vector3(start + perpendicular, 0), color),
            new(new Vector3(start - perpendicular, 0), color),
            new(new Vector3(end - perpendicular, 0), color),
            new(new Vector3(end + perpendicular, 0), color),
        };

        var indices = new int[]
        {
            0, 1, 2,
            0, 2, 3
        };

        entity.Set(new DrawComponent
        {
            Type = DrawElementType.Mesh,
            Vertices = vertices,
            Indices = indices,
            PrimitiveType = PrimitiveType.TriangleList,
            Target = _renderTarget,
            LayerDepth = DebugLayerDepth + 0.0005f  // Between bounds and circle
        });
    }

    public void Dispose()
    {
        foreach (var entity in _debugEntities)
        {
            if (entity.IsAlive)
            {
                entity.Dispose();
            }
        }
        _debugEntities.Clear();
        _spriteEntities.Dispose();
    }
}

using System;
using DefaultEcs;
using DefaultEcs.System;
using Microsoft.Xna.Framework;
using MonoDreams.Component;
using MonoDreams.Draw;
using MonoDreams.Component.Draw;
using MonoDreams.State;

namespace MonoDreams.System.Draw;

[With(typeof(SpriteInfo), typeof(Transform))]
public class CullingSystem(World world, MonoDreams.Component.Camera camera) : AEntitySetSystem<GameState>(world)
{
    public bool IsEnabled { get; set; } = true;
    public bool DebugEnabled { get; set; } = false;
    public int DebugMargin { get; set; } = 50;

    private Entity? _debugEntity;
    private Rectangle _cullBounds;

    protected override void PreUpdate(GameState state)
    {
        // Compute the effective culling bounds for this frame
        _cullBounds = camera.VirtualScreenBounds;

        if (DebugEnabled)
        {
            // DebugMargin is in screen pixels — convert to world units for culling
            var worldMarginX = (int)Math.Min(DebugMargin / camera.Zoom, _cullBounds.Width * 0.5f - 1);
            var worldMarginY = (int)Math.Min(DebugMargin / camera.Zoom, _cullBounds.Height * 0.5f - 1);
            worldMarginX = Math.Max(0, worldMarginX);
            worldMarginY = Math.Max(0, worldMarginY);

            _cullBounds = new Rectangle(
                _cullBounds.X + worldMarginX,
                _cullBounds.Y + worldMarginY,
                _cullBounds.Width - worldMarginX * 2,
                _cullBounds.Height - worldMarginY * 2);

            // Create or update the debug outline entity
            if (_debugEntity == null || !_debugEntity.Value.IsAlive)
            {
                _debugEntity = world.CreateEntity();
                _debugEntity.Value.Set(new Transform());
                _debugEntity.Value.Set(new DrawComponent { Target = RenderTargetID.HUD });
                _debugEntity.Value.Set<Visible>();
            }

            // HUD uses Matrix.Identity — DebugMargin is already in screen pixels
            var debugRect = new Rectangle(
                DebugMargin, DebugMargin,
                camera.VirtualWidth - DebugMargin * 2,
                camera.VirtualHeight - DebugMargin * 2);

            var generator = new RectangleOutlineMeshGenerator(debugRect, 2f, Color.Lime);
            _debugEntity.Value.Get<DrawComponent>().SetMeshData(generator);
        }
        else if (_debugEntity != null && _debugEntity.Value.IsAlive)
        {
            _debugEntity.Value.Dispose();
            _debugEntity = null;
        }
    }

    protected override void Update(GameState state, in Entity entity)
    {
        var spriteInfo = entity.Get<SpriteInfo>();

        // Only cull world-space entities (Main render target)
        // UI/HUD entities use screen coordinates — camera culling doesn't apply
        if (spriteInfo.Target != RenderTargetID.Main) return;

        var transform = entity.Get<Transform>();

        // Calculate scale from source to destination (matches MasterRenderSystem logic)
        var scaleX = spriteInfo.Source.Width > 0 ? spriteInfo.Size.X / spriteInfo.Source.Width : 1f;
        var scaleY = spriteInfo.Source.Height > 0 ? spriteInfo.Size.Y / spriteInfo.Source.Height : 1f;

        // Entity bounds must account for origin offset to match how SpriteBatch.Draw renders:
        // visual position = worldPosition + offset - origin * scale
        var entityBounds = new Rectangle(
            (int)(transform.WorldPosition.X + spriteInfo.Offset.X - spriteInfo.Origin.X * scaleX),
            (int)(transform.WorldPosition.Y + spriteInfo.Offset.Y - spriteInfo.Origin.Y * scaleY),
            (int)spriteInfo.Size.X,
            (int)spriteInfo.Size.Y
        );

        var isVisible = _cullBounds.Intersects(entityBounds);

        if (isVisible)
        {
            if (!entity.Has<Visible>())
            {
                entity.Set<Visible>();
            }
        }
        else
        {
            if (entity.Has<Visible>())
            {
                entity.Remove<Visible>();
            }
        }
    }

    public override void Dispose()
    {
        if (_debugEntity != null && _debugEntity.Value.IsAlive)
        {
            _debugEntity.Value.Dispose();
            _debugEntity = null;
        }
        base.Dispose();
    }
}

